def transform(grid):
    h, w = len(grid), len(grid[0])
    labels = [[-1] * w for _ in range(h)]
    colors = {}
    component = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or labels[r][c] != -1:
                continue
            labels[r][c] = component
            q = [(r, c)]
            for i, j in q:
                if grid[i][j] not in (0, 1):
                    colors[component] = grid[i][j]
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] != 0 and labels[ni][nj] == -1:
                        labels[ni][nj] = component
                        q.append((ni, nj))
            component += 1
    out = [row[:] for row in grid]
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if labels[r][c] in colors and all(grid[i][j] != 0 for i in range(r - 1, r + 2) for j in range(c - 1, c + 2)):
                out[r][c] = colors[labels[r][c]]
    return out
